/// Bind every parameter pattern as a `Target::Local` in `body_scope`.
fn bind_params(
    b: &mut Builder<'_>,
    path: &str,
    params_nid: &NodeId,
    body_scope: ScopeId,
    file: FileId,
    body_end: usize,
) {
    let facts = with_node(b, path, params_nid, |pf, n| {
        let mut out = Vec::new();
        let mut cursor = n.walk();
        for c in n.children(&mut cursor) {
            if c.kind() == "parameter" {
                let annotation = c
                    .child_by_field_name("type")
                    .map(|ty| pf.node_text(&ty).trim().to_string())
                    .filter(|s| !s.is_empty());
                if let Some(p) = c.child_by_field_name("pattern") {
                    let mut names = Vec::new();
                    pattern_idents(pf, &p, &mut names);
                    for name in names {
                        out.push((
                            name,
                            LocalFact {
                                kind: BindingKind::Param,
                                annotation: annotation.clone(),
                                init: None,
                            },
                        ));
                    }
                }
            }
        }
        out
    });
    // A single `add_locals` call over the full ordered slice keeps the
    // enumerate-based `BindingRef.ordinal` (0, 1, 2, …) identical to the
    // parent commit; per-param `local_facts` are then attached by def_byte
    // below, not by splitting this into one `add_locals` call per name
    // (that would collapse every ordinal to 0 — see the amend note on this
    // commit).
    let names: Vec<(String, usize)> = facts.iter().map(|(name, _)| name.clone()).collect();
    add_locals(
        b,
        body_scope,
        file,
        body_end,
        &names,
        LocalFact {
            kind: BindingKind::Param,
            annotation: None,
            init: None,
        },
    );

